import fcntl,hashlib,json,pathlib,random,statistics,subprocess,time
p=pathlib.Path(__file__).resolve().parent
variants=['baseline','control','sift','fused','singleton']
records={};build=[]
for cc,compiler in [('gcc','g++'),('clang','clang++')]:
 for v in variants:
  exe=p/f'{cc}_{v}'
  cmd=['taskset','-c','8',compiler,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS','-DHEADER="'+str(p/f'{v}.hpp')+'"',str(p/'bench.cpp'),'-o',str(exe)]
  if cc=='clang':cmd.insert(4,'--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15')
  # autodetect actual GCC install separately below if needed
  run=subprocess.run(cmd,text=True,capture_output=True)
  if run.returncode:raise RuntimeError(str(cmd)+'\n'+run.stderr)
  build.append({'cmd':cmd,'binary_sha256':hashlib.sha256(exe.read_bytes()).hexdigest()})
 print('built',cc,flush=True)
 with open('/tmp/sirkit_four_hours_20261022/benchmark_graph.lock','w') as lock:
  fcntl.flock(lock,fcntl.LOCK_EX)
  for kind in range(9):
   for n,reps in [(32,4000),(200000,5)]:
    vals={v:[] for v in variants};checks=set();rng=random.Random(100+kind+n)
    for rep in range(7):
     seq=variants[:];rng.shuffle(seq)
     for v in seq:
      out=subprocess.check_output(['taskset','-c','20',str(p/f'{cc}_{v}'),str(kind),str(n),str(reps)],text=True).split()
      vals[v].append(float(out[0]));checks.add(out[1])
    assert len(checks)==1, (kind,n,checks)
    med={v:statistics.median(a) for v,a in vals.items()};rat={v:med[v]/med['baseline'] for v in variants}
    records[f'{cc}/{kind}/{n}']={'raw_ms':vals,'median_ms':med,'ratio':rat,'checksum':checks.pop()}
    print(cc,kind,n,{v:round(x,3) for v,x in rat.items()},flush=True)
(p/'screen.json').write_text(json.dumps({'build':build,'records':records},indent=2)+'\n')

